Method.Implementation:
try {
	set oldID = $IO
	// Compile line generates output to console; causes javascript to throw error
	OPEN "/dev/null/" 
	USE "/dev/null/"
  	set status = ##class(%SYSTEM.OBJ).Export(.cls, .flNm)
  	CLOSE "/dev/null/"

	OPEN oldID
	USE oldID 

  return status 
} catch exp
{
	return $System _ " / " _ $NAMESPACE _ " = " _ flNm _", Name: "_exp.Name _ ", Location: "_exp.Location_ ", Code: "_exp.Code_ ", Data: "_exp.Data _", log: " _ errLog
}

set errLog = ""
try {
	//Do str.Rewind()
	// WRITE !, "Import: " _ flNm
	set oldID = $IO
	// Compile line generates output to console; causes javascript to throw error
	OPEN "/dev/null/" 
	USE "/dev/null/"

 	set status = ##class(%SYSTEM.OBJ).Load(flNm, opt, .errLog)
  	// set status = $system.OBJ.LoadStream(str, opt, .errLog)

  	CLOSE "/dev/null/"

	OPEN oldID
	USE oldID 

  return status _ " : " _ errLog _ ": " _ flNm
} catch exp
{
	return "Exception: " _ $System _ " / " _ $NAMESPACE _ " = " _ flNm _", Name: "_exp.Name _ ", Location: "_exp.Location_ ", Code: "_exp.Code_ ", Data: "_exp.Data _", log: " _ errLog
}
